// Revisa lo que devolvió el scraper para una fuente y arma los datos
// para fn_guardar_noticias: sin títulos vacíos, sin URL repetidas y con
// categorías y fechas válidas. Si el scraper no respondió, se registra el error.
const CATEGORIAS = ['curso', 'convocatoria', 'certificacion', 'noticia'];
const fuente = $('Leer fuentes activas').item.json;
const respuesta = $json;

let error = null;
if (respuesta.error) {
  error = typeof respuesta.error === 'string'
    ? respuesta.error
    : `El scraper no respondió: ${respuesta.error.message ?? 'error desconocido'}`;
}

const vistas = new Set();
const noticias = [];
for (const n of (Array.isArray(respuesta.noticias) ? respuesta.noticias : [])) {
  const titulo = String(n.titulo ?? '').replace(/\s+/g, ' ').trim();
  const url = String(n.url ?? '').trim();
  if (!titulo || !/^https?:\/\//.test(url) || vistas.has(url)) continue;
  if (!/^[0-9a-f]{64}$/.test(String(n.hash_contenido ?? ''))) continue;
  vistas.add(url);
  noticias.push({
    titulo: titulo.slice(0, 300),
    url,
    resumen: n.resumen ? String(n.resumen).slice(0, 500) : null,
    categoria: CATEGORIAS.includes(n.categoria) ? n.categoria : 'noticia',
    fecha_publicacion: /^\d{4}-\d{2}-\d{2}$/.test(String(n.fecha_publicacion ?? '')) ? n.fecha_publicacion : null,
    hash_contenido: n.hash_contenido,
  });
}

return {
  json: {
    fuente_id: fuente.fuente_id,
    fuente: fuente.nombre,
    // Si el scraper no respondió no se sabe qué dice robots.txt: se conserva el valor anterior
    permitido: typeof respuesta.permitido_robots === 'boolean' ? respuesta.permitido_robots : fuente.permitido_robots,
    error,
    iniciado_en: respuesta.revisado_en ?? null,
    noticias,
  },
};

// Resumen de la ejecución programada: una línea por fuente
const filas = $input.all().map((item, i) => {
  const entrada = $('Limpiar y deduplicar').all()[i]?.json ?? {};
  const r = item.json;
  return {
    fuente: entrada.fuente,
    estado: r.estado ?? 'fallida',
    nuevas: r.nuevas ?? 0,
    actualizadas: r.actualizadas ?? 0,
    sin_cambios: r.sin_cambios ?? 0,
    error: entrada.error ?? r.error?.message ?? null,
  };
});

return [{
  json: {
    fuentes: filas.length,
    nuevas: filas.reduce((s, f) => s + f.nuevas, 0),
    actualizadas: filas.reduce((s, f) => s + f.actualizadas, 0),
    fallidas: filas.filter((f) => f.estado !== 'exitosa').length,
    detalle: filas,
  },
}];

// Normaliza la categoría y el límite que pide el agente
const CATEGORIAS = ['curso', 'convocatoria', 'certificacion', 'noticia'];
const entrada = $input.first().json;
const categoria = String(entrada.categoria ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().trim().replace(/s$/, '');
const limite = Math.min(Math.max(parseInt(entrada.limite, 10) || 5, 1), 10);

return [{ json: { categoria: CATEGORIAS.includes(categoria) ? categoria : '', limite } }];

// Entrega al agente las novedades con su fuente, enlace y fecha
const filas = $input.all().map((item) => item.json).filter((fila) => fila.titulo);
const parametros = $('Normalizar parámetros').first().json;

if (filas.length === 0) {
  return [{
    json: {
      encontrado: false,
      categoria: parametros.categoria || 'todas',
      mensaje: 'Todavía no hay noticias recopiladas para esa categoría.',
      noticias: [],
    },
  }];
}

return [{
  json: {
    encontrado: true,
    categoria: parametros.categoria || 'todas',
    total: filas.length,
    noticias: filas.map((fila) => ({
      titulo: fila.titulo,
      resumen: fila.resumen ? String(fila.resumen).slice(0, 400) : null,
      categoria: fila.categoria,
      fecha_publicacion: fila.fecha_publicacion,
      fuente: fila.fuente,
      url: fila.url,
    })),
  },
}];
